export async function createSecretStore(
  options: SecretStoreOptions,
): Promise<SecretStore> {
  const { storage, masterPassword } = options;

  // Derive AES-256 key from master password using PBKDF2
  const enc = new TextEncoder();
  const passwordBytes = enc.encode(masterPassword);

  const baseKey = await crypto.subtle.importKey(
    "raw",
    passwordBytes,
    "PBKDF2",
    false,
    ["deriveKey"],
  );

  const fixedSalt = enc.encode("secret-store-v1-salt");

  const aesKey = await crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt: fixedSalt,
      iterations: 100000,
      hash: "SHA-256",
    },
    baseKey,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );

  // Helper: base64url encode/decode
  function base64urlEncode(data: Uint8Array): string {
    let binary = "";
    for (let i = 0; i < data.length; i++) {
      binary += String.fromCharCode(data[i]);
    }
    return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }

  function base64urlDecode(str: string): Uint8Array {
    let base64 = str.replace(/-/g, "+").replace(/_/g, "/");
    while (base64.length % 4) base64 += "=";
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  }

  function makeKey(owner: string, name: string): string {
    return `secret/${base64urlEncode(enc.encode(owner))}/${base64urlEncode(enc.encode(name))}`;
  }

  function ownerPrefix(owner: string): string {
    return `secret/${base64urlEncode(enc.encode(owner))}/`;
  }

  return {
    async put(owner: string, name: string, value: string): Promise<void> {
      const key = makeKey(owner, name);
      const nonce = crypto.getRandomValues(new Uint8Array(12));
      const aad = enc.encode(key); // Use the full storage key as AAD
      const valueBytes = enc.encode(value);

      const ciphertext = await crypto.subtle.encrypt(
        { name: "AES-GCM", nonce, additionalData: aad },
        aesKey,
        valueBytes,
      );

      // Combine nonce + ciphertext
      const combined = new Uint8Array(12 + ciphertext.byteLength);
      combined.set(nonce, 0);
      combined.set(new Uint8Array(ciphertext), 12);

      const stored = base64urlEncode(combined);
      await storage.set(key, stored);
