          { name: "AES-GCM", nonce, additionalData: aad },
          aesKey,
          ciphertext,
        );
        return new TextDecoder().decode(decrypted);
      } catch {
        throw new Error("Decryption failed: data may have been tampered with");
      }
    },

    async list(owner: string): Promise<string[]> {
      const prefix = ownerPrefix(owner);
      const allKeys = await storage.keys();
      const names: string[] = [];

      for (const k of allKeys) {
        if (k.startsWith(prefix)) {
          const nameEncoded = k.slice(prefix.length);
          try {
            const nameBytes = base64urlDecode(nameEncoded);
            names.push(new TextDecoder().decode(nameBytes));
          } catch {
            // Skip malformed entries
          }
        }
      }

      names.sort();
      return names;
    },

    async remove(owner: string, name: string): Promise<boolean> {
      const key = makeKey(owner, name);
      const stored = await storage.get(key);
      if (stored === undefined) return false;
      await storage.delete(key);
      return true;
    },
  };
}
